package uk.payapi.kilotaxi;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import java.util.Locale;

public class MainActivity extends Activity {
    private LinearLayout layout;
    private TextView summary,message;
    private EditText server,username,password;
    private Button start,waiting,pause,resume,finish,logout;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private boolean busy=false,loggedIn=false;
    private String pending="start";
    private final Runnable refresh=new Runnable(){public void run(){render();handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);Engine.init(this);showLogin();}
    private void page(String title){ScrollView scroll=new ScrollView(this);layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(28,40,28,40);layout.setBackgroundColor(Color.rgb(244,247,242));scroll.setFillViewport(true);scroll.addView(layout);setContentView(scroll);TextView brand=new TextView(this);brand.setText("KILO TAXI · DRIVER");brand.setTextColor(Color.rgb(30,100,75));brand.setTextSize(13);layout.addView(brand);TextView heading=new TextView(this);heading.setText(title);heading.setTextSize(30);heading.setTextColor(Color.rgb(24,61,50));heading.setPadding(0,14,0,22);layout.addView(heading);}
    private TextView text(String value){TextView v=new TextView(this);v.setText(value);v.setTextSize(16);v.setPadding(0,8,0,12);layout.addView(v);return v;}
    private EditText input(String hint,String value,boolean secret){EditText v=new EditText(this);v.setHint(hint);v.setText(value);v.setSingleLine(true);v.setTextSize(16);if(secret)v.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);else v.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);v.setMinHeight((int)(52*getResources().getDisplayMetrics().density));layout.addView(v,new LinearLayout.LayoutParams(-1,-2));return v;}
    private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(26,88,66)));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.setMargins(0,12,0,0);layout.addView(b,params);b.setOnClickListener(v->action.run());return b;}
    private void showLogin(){loggedIn=false;page("အကောင့်ဝင်ရန်");text("Admin ဖန်တီးပေးထားသော account နဲ့ ဝင်ပါ။ Password ကို ဖုန်းထဲ မသိမ်းပါ။");server=input("HTTPS server",Engine.origin(),false);username=input("Username","",false);password=input("Password","",true);message=text("");button("ဝင်မယ်",()->{if(busy)return;try{String target=Engine.normalize(server.getText().toString());Engine.prefs.edit().putString("origin",target).remove("cookie").apply();JSONObject body=new JSONObject().put("username",username.getText().toString().trim()).put("password",password.getText().toString());busy=true;message.setText("Login ဝင်နေပါတယ်…");Engine.queue.execute(()->{try{Engine.user=Engine.call("login",body);Engine.apply(Engine.call("meter",null));runOnUiThread(()->{password.setText("");showMeter();});}catch(Exception e){runOnUiThread(()->message.setText(e.getMessage()));}finally{busy=false;}});}catch(Exception e){message.setText(e.getMessage());}});}
    private void showMeter(){loggedIn=true;page("တိုက်ရိုက်ကားမီတာ");if(Engine.user!=null)text(Engine.user.optString("name")+" · "+Engine.user.optString("vehicleNumber"));summary=text("");summary.setTextSize(25);message=text(Engine.status);text("ခရီးစပြီးနောက် GPS ကို screen ပိတ်ထားချိန်ပါ အသုံးပြုပါတယ်။ ခရီးဆုံး / Pause နှိပ်လျှင် GPS service ရပ်ပါမယ်။ Waiting ပထမ 10 မိနစ် အခမဲ့ပါ။ Internet မရချိန်က km ကို ခန့်မှန်းမဖြည့်ပါ။");start=button("ခရီးစမယ် / GPS ဆက်ချိတ်မယ်",()->requestTrack("start"));waiting=button("Waiting ON / OFF",()->requestTrack("waiting"));pause=button("ခေတ္တရပ်ရန်",()->action("pause"));resume=button("ပြန်စရန်",()->requestTrack("resume"));finish=button("ခရီးဆုံး · သိမ်းရန်",()->new AlertDialog.Builder(this).setTitle("ခရီးဆုံးမလား?").setMessage("History ထဲ ခရီးကို သိမ်းပါမယ်။").setNegativeButton("မဆုံးသေးပါ",null).setPositiveButton("သိမ်းမယ်",(d,w)->action("finish")).show());button("History / Admin website",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(Engine.origin()+"/history"))));logout=button("Logout",()->{if(Engine.active())return;Engine.queue.execute(()->{try{Engine.call("logout",new JSONObject());}catch(Exception ignored){}Engine.prefs.edit().remove("cookie").apply();runOnUiThread(this::showLogin);});});render();}
    private boolean mayDrive(){if(Engine.user==null)return false;String permissions=Engine.user.optJSONArray("permissions").toString();return permissions.contains("calculate")&&permissions.contains("save_trips");}
    private void render(){if(!loggedIn||summary==null)return;if(Engine.prefs.getString("cookie","").isEmpty()&&!Engine.tracking){showLogin();return;}JSONObject m=Engine.meter;long seconds=m==null?0:(long)m.optDouble("waitingSeconds");summary.setText(String.format(Locale.US,"%.3f km\n%.0f ကျပ်\nစောင့်ချိန် %d စက္ကန့်\n%s",m==null?0:m.optDouble("km"),m==null?0:m.optDouble("total"),seconds,m==null?"OFF":m.optString("state")));message.setText(Engine.status+"\nGPS accuracy: "+Engine.accuracy+(Engine.tracking?" · Background GPS ON":" · GPS OFF"));boolean allowed=mayDrive()&&!busy;start.setEnabled(allowed&&!Engine.tracking);waiting.setEnabled(allowed&&Engine.active()&&!"paused".equals(m.optString("state")));waiting.setText(m!=null&&m.optBoolean("waitingEnabled")?"Waiting OFF":"Waiting ON");pause.setEnabled(allowed&&Engine.active()&&!"paused".equals(m.optString("state")));resume.setEnabled(allowed&&Engine.active()&&"paused".equals(m.optString("state")));finish.setEnabled(allowed&&Engine.active());logout.setEnabled(!busy&&!Engine.active());}
    private void requestTrack(String action){pending=action;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setTitle("ခရီးအတွင်း GPS အသုံးပြုခွင့်").setMessage("ခရီး km နဲ့ history လမ်းကြောင်းမှတ်ရန် Precise Location လိုပါတယ်။ ခရီးစနေချိန် app ကို နောက်ခံပို့ထားလည်း notification နဲ့ GPS ဆက်မှတ်ပါမယ်။").setNegativeButton("မလုပ်သေးပါ",null).setPositiveButton("ခွင့်ပြုမယ်",(d,w)->{String[] permissions=Build.VERSION.SDK_INT>=33?new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.POST_NOTIFICATIONS}:new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION};requestPermissions(permissions,7);}).show();return;}action(action);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==7){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)action(pending);else new AlertDialog.Builder(this).setMessage("Precise Location ခွင့်ပြုပါ။ ပိတ်ထားပြီးသားဆို App Settings မှာ ပြန်ဖွင့်ပါ။").setPositiveButton("Settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())))).setNegativeButton("ပိတ်ရန်",null).show();}}
    private void action(String action){if(busy)return;busy=true;render();Engine.queue.execute(()->{try{if(action.equals("start")){if(!Engine.active())Engine.apply(Engine.call("meter/start",new JSONObject()));else Engine.apply(Engine.call("meter",null));}else{String type=action.equals("waiting")?(Engine.meter.optBoolean("waitingEnabled")?"waiting_off":"waiting_on"):action;Engine.apply(Engine.call("meter/"+Engine.meter.getString("id"),new JSONObject().put("type",type)));}Engine.status="မီတာ sync ဖြစ်နေပါတယ်။";runOnUiThread(()->{try{if(Engine.shouldTrack())startForegroundService(new Intent(this,TrackingService.class));else stopService(new Intent(this,TrackingService.class));}catch(Exception e){Engine.status="App ကို အရှေ့မှာဖွင့်ပြီး GPS ဆက်ချိတ်မယ် ကိုနှိပ်ပါ။ "+e.getMessage();}});}catch(Exception e){Engine.status=e.getMessage();}finally{busy=false;runOnUiThread(this::render);}});}
    @Override protected void onResume(){super.onResume();handler.post(refresh);if(!loggedIn&&!Engine.prefs.getString("cookie","").isEmpty()){Engine.queue.execute(()->{try{Engine.user=Engine.call("me",null);Engine.apply(Engine.call("meter",null));runOnUiThread(this::showMeter);}catch(Exception e){Engine.status=e.getMessage();}});}}
    @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
